<script>
(()=>{const form=document.querySelector('[data-batch-consumption]');if(!form||form.dataset.ready)return;form.dataset.ready='1';const company=form.querySelector('[data-batch-company]'),material=form.querySelector('[data-batch-material]'),materialQuery=form.querySelector('[data-material-query]'),materialMenu=form.querySelector('[data-material-menu]'),type=form.querySelector('[data-batch-type]'),monthlyFields=form.querySelector('[data-monthly-fields]'),dateSection=form.querySelector('[data-datewise-section]'),periodsBox=form.querySelector('[data-periods]'),cards=[...form.querySelectorAll('[data-plant-card]')],empty=form.querySelector('[data-empty-plants]'),selectAll=form.querySelector('[data-select-all]'),materialPlants=@json($materialPlants),stockMap=@json($stockMap),nextDates=@json($monthlyNextDates),materialOptions=[...material.options].filter(option=>option.value);let periodCount=0;
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const addDay=value=>{const d=new Date(value+'T00:00:00');d.setDate(d.getDate()+1);return iso(d)};const monthEnd=value=>{const d=new Date(value+'T00:00:00');return iso(new Date(d.getFullYear(),d.getMonth()+1,0))};const updateDays=()=>{const input=form.querySelector('[name=monthly_date]'),out=form.querySelector('[data-monthly-days]');if(!input.value){out.value='';return}const d=new Date(input.value+'T00:00:00');out.value=new Date(d.getFullYear(),d.getMonth()+1,0).getDate()-d.getDate()+1};
const closeMaterialMenu=()=>materialMenu.hidden=true;const chooseMaterial=option=>{material.value=option.value;materialQuery.value=option.textContent.trim();materialQuery.setCustomValidity('');closeMaterialMenu();material.dispatchEvent(new Event('change',{bubbles:true}))};const renderMaterialMenu=()=>{const words=materialQuery.value.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean),matches=materialOptions.filter(option=>{const haystack=(option.dataset.searchTerms||option.textContent).toLocaleLowerCase();return words.every(word=>haystack.includes(word))});materialMenu.replaceChildren();if(!matches.length){const message=document.createElement('div');message.className='batch-material-empty';message.textContent='No matching materials found';materialMenu.appendChild(message)}else matches.forEach(option=>{const button=document.createElement('button'),title=document.createElement('strong');button.type='button';button.className='batch-material-option';title.textContent=`${option.value} - ${option.dataset.name||''}`;button.appendChild(title);if(option.dataset.group){const group=document.createElement('small');group.textContent=`Group: ${option.dataset.group}`;button.appendChild(group)}button.addEventListener('mousedown',event=>{event.preventDefault();chooseMaterial(option)});materialMenu.appendChild(button)});materialMenu.hidden=false};materialQuery.addEventListener('focus',renderMaterialMenu);materialQuery.addEventListener('input',()=>{material.value='';materialQuery.setCustomValidity('Please select a material from the list.');filterPlants();renderMaterialMenu()});materialQuery.addEventListener('keydown',event=>{if(event.key==='Escape')closeMaterialMenu();if(event.key==='Enter'&&!materialMenu.hidden){event.preventDefault();const first=materialMenu.querySelector('.batch-material-option');if(first)first.dispatchEvent(new MouseEvent('mousedown',{bubbles:true}))}});materialQuery.addEventListener('blur',()=>setTimeout(closeMaterialMenu,120));if(material.value){const selected=materialOptions.find(option=>option.value===material.value);if(selected)materialQuery.value=selected.textContent.trim()}
