const periodDays=row=>{const from=row.querySelector('[data-from]').value,until=row.querySelector('[data-until]').value,out=row.querySelector('[data-period-days]');if(!from||!until){out.value='';return}const start=new Date(from+'T00:00:00'),end=new Date(until+'T00:00:00');out.value=end>=start?Math.floor((end-start)/86400000)+1:''};
const reindex=()=>{[...periodsBox.querySelectorAll('[data-period]')].forEach((row,index)=>{row.querySelector('[data-from]').name=`periods[${index}][from]`;row.querySelector('[data-until]').name=`periods[${index}][until]`;row.querySelector('[data-remove]').hidden=index===0;periodDays(row)});syncPlantInputs()};
const addPeriod=()=>{const prev=periodsBox.lastElementChild?.querySelector('[data-until]')?.value,start=prev?addDay(prev):iso(new Date()),end=monthEnd(start);const row=document.createElement('div');row.className='batch-period';row.dataset.period='1';row.innerHTML=`<label class="batch-field"><span>Effective from *</span><input type="date" min="${iso(new Date())}" value="${start}" required data-from></label><label class="batch-field"><span>Effective until *</span><input type="date" min="${start}" value="${end}" required data-until></label><label class="batch-field"><span>No. of days</span><input type="text" value="1" readonly data-period-days></label><button type="button" title="Remove period" data-remove>×</button>`;row.querySelector('[data-remove]').onclick=()=>{row.remove();reindex()};const fromInput=row.querySelector('[data-from]'),untilInput=row.querySelector('[data-until]'),onFromChange=()=>{const from=fromInput.value;untilInput.min=from;if(!untilInput.value||untilInput.value<from)untilInput.value=monthEnd(from);periodDays(row);syncPlantInputs()},onUntilChange=()=>{periodDays(row);const next=row.nextElementSibling?.querySelector('[data-from]');if(next&&untilInput.value){next.value=addDay(untilInput.value);next.dispatchEvent(new Event('input',{bubbles:true}))}syncPlantInputs()};['input','change'].forEach(eventName=>{fromInput.addEventListener(eventName,onFromChange);untilInput.addEventListener(eventName,onUntilChange)});periodsBox.appendChild(row);periodCount++;reindex()};
const filterPlants=()=>{const hasMaterial=Boolean(material.value);let shown=0;cards.forEach(card=>{card.hidden=card.dataset.company!==company.value||!hasMaterial;const box=card.querySelector('[data-plant-selected]');box.checked=!card.hidden;card.classList.toggle('selected',!card.hidden);if(!card.hidden){shown++;card.querySelector('[data-plant-stock]').textContent=Number(stockMap[`${material.value}|${card.dataset.code}`]||0).toLocaleString('en-IN',{minimumFractionDigits:3,maximumFractionDigits:3})+' MT'}});empty.hidden=shown>0;form.querySelector('[data-plant-table-head]').hidden=shown===0;selectAll.checked=shown>0;syncPlantInputs()};
const toggleType=()=>{const isDate=type.value==='datewise';monthlyFields.hidden=isDate;dateSection.hidden=!isDate;form.querySelector('[data-plant-helper]').textContent=isDate?'Enter daily consumption for every plant and period.':'Enter daily consumption for all applicable plants.';if(isDate&&!periodsBox.children.length)addPeriod();syncPlantInputs()};
cards.forEach(card=>card.querySelector('[data-plant-selected]').addEventListener('change',e=>{card.classList.toggle('selected',e.target.checked);syncPlantInputs()}));selectAll.addEventListener('change',()=>cards.filter(c=>!c.hidden).forEach(c=>{const box=c.querySelector('[data-plant-selected]');box.checked=selectAll.checked;box.dispatchEvent(new Event('change'))}));company.addEventListener('change',filterPlants);material.addEventListener('change',filterPlants);type.addEventListener('change',toggleType);if(window.jQuery){window.jQuery(material).off('change.batchConsumption').on('change.batchConsumption',filterPlants);window.jQuery(company).off('change.batchConsumption').on('change.batchConsumption',filterPlants);window.jQuery(type).off('change.batchConsumption').on('change.batchConsumption',toggleType)}['input','change'].forEach(eventName=>form.querySelector('[name=monthly_date]').addEventListener(eventName,updateDays));form.querySelector('[data-add-period]').addEventListener('click',addPeriod);cards.forEach(c=>c.classList.add('selected'));updateDays();filterPlants();toggleType()})();
</script>
@endsection
